#include <iostream>
#include <string>

int main() {
    std::string inputStr;
    std::getline(std::cin, inputStr);
    // Remove leading and trailing whitespace
    size_t start = inputStr.find_first_not_of(" \t\n\r");
    size_t end = inputStr.find_last_not_of(" \t\n\r");
    if (start == std::string::npos) {
        inputStr = "";
    } else {
        inputStr = inputStr.substr(start, end - start + 1);
    }

    int length = inputStr.length();
    int countEvenSequences = 0;
    int sequenceLength = 1;

    for (int i = 0; i < length - 1; i++) {
        if (inputStr[i] == inputStr[i + 1]) {
            sequenceLength++;
        } else {
            if (sequenceLength % 2 == 0) {
                countEvenSequences++;
            }
            sequenceLength = 1;
        }
    }
    if (sequenceLength % 2 == 0) {
        countEvenSequences++;
    }
    std::cout << countEvenSequences << std::endl;
    return 0;
}
